 */
public class OpenAiModelConfigurationTests {

    private final ApplicationContextRunner contextRunner = new ApplicationContextRunner().withPropertyValues("spring.ai.openai.api-key=API_KEY", "spring.ai.openai.base-url=TEST_BASE_URL");

    @Test
    void chatModelActivation() {
        this.contextRunner.withConfiguration(SpringAiTestAutoConfigurations.of(OpenAiChatAutoConfiguration.class)).run(context -> {
            assertThat(context.getBeansOfType(OpenAiApi.class)).isNotEmpty();
            assertThat(context.getBeansOfType(OpenAiChatModel.class)).isNotEmpty();
            assertThat(context.getBeansOfType(OpenAiEmbeddingModel.class)).isEmpty();
            assertThat(context.getBeansOfType(OpenAiImageModel.class)).isEmpty();
            assertThat(context.getBeansOfType(OpenAiAudioSpeechModel.class)).isEmpty();
            assertThat(context.getBeansOfType(OpenAiAudioTranscriptionModel.class)).isEmpty();
            assertThat(context.getBeansOfType(OpenAiModerationModel.class)).isEmpty();
        });
        this.contextRunner.withConfiguration(SpringAiTestAutoConfigurations.of(OpenAiChatAutoConfiguration.class)).withPropertyValues("spring.ai.model.chat=none").run(context -> {
            assertThat(context.getBeansOfType(OpenAiChatProperties.class)).isEmpty();
            assertThat(context.getBeansOfType(OpenAiChatModel.class)).isEmpty();
        });
        this.contextRunner.withConfiguration(SpringAiTestAutoConfigurations.of(OpenAiChatAutoConfiguration.class)).withPropertyValues("spring.ai.model.chat=openai").run(context -> {
            assertThat(context.getBeansOfType(OpenAiChatProperties.class)).isNotEmpty();
            assertThat(context.getBeansOfType(OpenAiChatModel.class)).isNotEmpty();
        });
        this.contextRunner.withConfiguration(SpringAiTestAutoConfigurations.of(OpenAiChatAutoConfiguration.class, OpenAiEmbeddingAutoConfiguration.class, OpenAiImageAutoConfiguration.class, OpenAiAudioSpeechAutoConfiguration.class, OpenAiAudioTranscriptionAutoConfiguration.class, OpenAiModerationAutoConfiguration.class)).withPropertyValues("spring.ai.model.chat=openai", "spring.ai.model.embedding=none", "spring.ai.model.image=none", "spring.ai.model.audio.speech=none", "spring.ai.model.audio.transcription=none", "spring.ai.model.moderation=none").run(context -> {
            assertThat(context.getBeansOfType(OpenAiChatModel.class)).isNotEmpty();
            assertThat(context.getBeansOfType(OpenAiEmbeddingModel.class)).isEmpty();
            assertThat(context.getBeansOfType(OpenAiImageModel.class)).isEmpty();
            assertThat(context.getBeansOfType(OpenAiAudioSpeechModel.class)).isEmpty();
            assertThat(context.getBeansOfType(OpenAiAudioTranscriptionModel.class)).isEmpty();
            assertThat(context.getBeansOfType(OpenAiModerationModel.class)).isEmpty();
        });
    }

